import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Form, Button, InputGroup } from 'react-bootstrap';
import { useAuth } from '../contexts/AuthContext';
import { apiService, PurchaseRequest } from '../services/api';
import Toast from '../components/Toast';
import LoadingSpinner from '../components/LoadingSpinner';

interface ApprovedPurchaseRequestRow extends PurchaseRequest {
  selected: boolean;
}

const SupplierSearch: React.FC = () => {
  const { user } = useAuth();
  const [urls, setUrls] = useState<string[]>(['www.website1.com/', 'www.website2.com/', 'www.website3.com/', 'www.website4.com/']);
  const [newUrl, setNewUrl] = useState('');
  const [approvedPRs, setApprovedPRs] = useState<ApprovedPurchaseRequestRow[]>([]);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [loadingApprovedPRs, setLoadingApprovedPRs] = useState(false);

  useEffect(() => {
    loadApprovedPurchaseRequests();
  }, []);

  const loadApprovedPurchaseRequests = async () => {
    try {
      setLoadingApprovedPRs(true);
      const prs = await apiService.getPurchaseRequests(false);
      const approved = prs
        .filter((pr) => pr.status?.toLowerCase() === 'approved')
        .map((pr) => ({ ...pr, selected: false }));
      setApprovedPRs(approved);
    } catch (error) {
      console.error('Failed to load approved purchase requests:', error);
      setApprovedPRs([]);
    } finally {
      setLoadingApprovedPRs(false);
    }
  };

  const handleAddUrl = () => {
    if (newUrl.trim()) {
      setUrls([...urls, newUrl.trim()]);
      setNewUrl('');
    }
  };

  const handleRemoveUrl = (index: number) => {
    setUrls(urls.filter((_, i) => i !== index));
  };

  const handleUrlChange = (index: number, value: string) => {
    const newUrls = [...urls];
    newUrls[index] = value;
    setUrls(newUrls);
  };

  const toggleSelectAllApproved = (checked: boolean) => {
    setApprovedPRs((rows) => rows.map((r) => ({ ...r, selected: checked })));
  };

  const toggleSelectApproved = (id: string) => {
    setApprovedPRs((rows) => rows.map((r) => (r.id === id ? { ...r, selected: !r.selected } : r)));
  };

  const handleUseSelected = () => {
    const selected = approvedPRs.filter((r) => r.selected);
    if (selected.length === 0) {
      setToastMessage('Please select at least one approved purchase request');
      setToastType('warning');
      setShowToast(true);
      return;
    }
    setToastMessage(`Selected ${selected.length} approved purchase request(s)`);
    setToastType('success');
    setShowToast(true);
    // TODO: Wire selected PRs to downstream flow
  };

  const allApprovedSelected = approvedPRs.length > 0 && approvedPRs.every((r) => r.selected);

  return (
    <Container fluid className="py-4">
      <Row className="mb-3">
        <Col>
          <h2 className="mb-1">Supplier Search</h2>
          <p className="text-muted mb-0">Manage URLs and select approved purchase requests.</p>
        </Col>
        <Col className="text-end">
          <Button variant="outline-primary" size="sm" onClick={loadApprovedPurchaseRequests} disabled={loadingApprovedPRs}>
            {loadingApprovedPRs ? (
              <>
                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true" />
                Refreshing...
              </>
            ) : (
              <>
                <i className="bi bi-arrow-clockwise me-2"></i>
                Refresh Approved PRs
              </>
            )}
          </Button>
        </Col>
      </Row>

      <Row>
        <Col md={6}>
          <Card className="mb-3">
            <Card.Body>
              <Form.Label className="fw-semibold">URL</Form.Label>
              {urls.map((url, index) => (
                <InputGroup key={index} className="mb-2">
                  <Form.Control
                    value={url}
                    onChange={(e) => handleUrlChange(index, e.target.value)}
                    placeholder="www.example.com/"
                  />
                  <Button variant="outline-danger" onClick={() => handleRemoveUrl(index)}>
                    <i className="bi bi-x"></i>
                  </Button>
                </InputGroup>
              ))}
              <InputGroup>
                <Form.Control
                  value={newUrl}
                  onChange={(e) => setNewUrl(e.target.value)}
                  placeholder="www.example.com/"
                  onKeyDown={(e) => e.key === 'Enter' && handleAddUrl()}
                />
                <Button variant="primary" onClick={handleAddUrl}>
                  Add
                </Button>
              </InputGroup>
            </Card.Body>
          </Card>
        </Col>

        <Col md={6}>
          <Card className="mb-3">
            <Card.Header className="d-flex justify-content-between align-items-center">
              <span className="fw-semibold">Approved Purchase Requests</span>
              <Form.Check
                type="checkbox"
                label="Select All"
                checked={allApprovedSelected}
                onChange={(e) => toggleSelectAllApproved(e.target.checked)}
              />
            </Card.Header>
            <Card.Body style={{ maxHeight: 320, overflowY: 'auto' }}>
              {loadingApprovedPRs ? (
                <div className="text-center py-2">
                  <LoadingSpinner size="sm" text="Loading..." />
                </div>
              ) : approvedPRs.length === 0 ? (
                <div className="text-muted">No approved purchase requests</div>
              ) : (
                approvedPRs.map((pr) => (
                  <Form.Check
                    key={pr.id}
                    type="checkbox"
                    checked={pr.selected}
                    onChange={() => toggleSelectApproved(pr.id)}
                    label={`${pr.pr_number} • ${pr.entity_name}`}
                    className="mb-1"
                  />
                ))
              )}
            </Card.Body>
            <Card.Footer className="text-end">
              <Button variant="primary" onClick={handleUseSelected} disabled={loadingApprovedPRs || approvedPRs.length === 0}>
                Use Selected
              </Button>
            </Card.Footer>
          </Card>
        </Col>
      </Row>

      <Toast
        show={showToast}
        message={toastMessage}
        type={toastType}
        onClose={() => setShowToast(false)}
      />
    </Container>
  );
};

export default SupplierSearch;
